for index, case in enumerate(cases):
    case['scores'] = {x:scores[x][case['id']] for x in ('A','B')}
    case['independent_initial_scores'] = {x:initial[x]['scores'][case['id']] for x in ('A','B')}
    case['operational_counts_not_economy_scores'] = {}
    for candidate in ('A','B'):
        c = mechanical[candidate]['cases'][index]
        case['operational_counts_not_economy_scores'][candidate] = dict(
            test_methods=c['baseline']['tests_run'], fixed_faults={f['id']:f['verdict'] for f in c['faults']},
            equivalent_refactors={r['id']:r['passed'] for r in c['refactors']},
            scope_passed=c['scope']['passed'], baseline_passed=c['baseline']['status']=='passed',
            independent_contract_passed=c['contract']['status']=='passed')
    case['maintenance_and_diagnostic_cost'] = 'См. отдельные строки ledger; количество методов и выбранных killed faults не используется как оценка экономности.'
    case['evidence'] = [f"original-cases/{mechanical['A']['cases'][index]['case']}/task.md"] + [f"R1/{x}/cases/{mechanical[x]['cases'][index]['case']}/" for x in ('A','B')]

